import React, { useState, useEffect, useMemo, useCallback } from "react";
import { useStatus } from "../contexts/StatusContext";
import { useI18n } from "../contexts/I18nContext";
import {
  UsersIcon,
  TasksIcon,
  ClockIcon,
  CpuIcon,
  ArrowUpIcon,
  ArrowDownIcon,
  ErrorIcon,
  CheckIcon,
  AlertIcon,
  ProcessingIcon,
  MemoryIcon,
  SpeedIcon,
  AnimatedHeartIcon,
  WarningIcon,
} from "./Icons";
import "../animations.css";

// Інтерфейси для типізації
interface SystemMetrics {
  cpu_usage: number;
  memory_usage: number;
  disk_usage: number;
  network_in: number;
  network_out: number;
  uptime: number;
  active_connections: number;
  tasks_per_second: number;
  error_rate: number;
}

interface ClientStats {
  total: number;
  connected: number;
  workers: number;
  apiWorkers: number;
  bots: number;
  streamHubs: number;
}

interface TaskStats {
  total: number;
  completed: number;
  failed: number;
  pending: number;
  processing: number;
}

// Компонент героїчної метрики
interface HeroMetricProps {
  title: string;
  value: string | number;
  subtitle: string;
  icon: React.ReactNode;
  gradient: string;
  trend?: {
    value: string;
    isPositive: boolean;
  };
  onClick?: () => void;
}

const HeroMetric: React.FC<HeroMetricProps> = ({
  title,
  value,
  subtitle,
  icon,
  gradient,
  trend,
  onClick,
}) => {
  return (
    <div 
      className={`relative overflow-hidden rounded-2xl p-8 text-white cursor-pointer transform transition-all duration-300 hover:scale-105 hover:shadow-2xl ${gradient} ${onClick ? 'hover:brightness-110' : ''}`}
      onClick={onClick}
    >
      <div className="relative z-10">
        <div className="flex items-center justify-between mb-4">
          <div className="p-3 bg-white/20 rounded-xl backdrop-blur-sm">
            {icon}
          </div>
          {trend && (
            <div className={`flex items-center space-x-1 px-3 py-1 rounded-full text-sm font-medium ${
              trend.isPositive ? 'bg-green-500/20 text-green-100' : 'bg-red-500/20 text-red-100'
            }`}>
              {trend.isPositive ? (
                <ArrowUpIcon size="sm" />
              ) : (
                <ArrowDownIcon size="sm" />
              )}
              <span>{trend.value}</span>
            </div>
          )}
        </div>
        <div className="space-y-2">
          <h3 className="text-lg font-medium opacity-90">{title}</h3>
          <div className="text-4xl font-bold">{value}</div>
          <p className="text-sm opacity-75">{subtitle}</p>
        </div>
      </div>

      {/* Декоративні елементи */}
      <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -translate-y-16 translate-x-16"></div>
      <div className="absolute bottom-0 left-0 w-24 h-24 bg-white/5 rounded-full translate-y-12 -translate-x-12"></div>
    </div>
  );
};

// Компонент статистичної картки
interface StatCardProps {
  title: string;
  value: string | number;
  change?: string;
  changeType?: "increase" | "decrease" | "neutral";
  icon: React.ReactNode;
  color: string;
  description?: string;
}

const StatCard: React.FC<StatCardProps> = ({
  title,
  value,
  change,
  changeType = "neutral",
  icon,
  color,
  description,
}) => {
  const changeColors = {
    increase: "text-emerald-600 bg-emerald-50",
    decrease: "text-red-600 bg-red-50",
    neutral: "text-slate-600 bg-slate-50",
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 hover:shadow-lg transition-all duration-300 hover:border-slate-300 group">
      <div className="flex items-start justify-between">
        <div className="flex-1">
          <div className="flex items-center space-x-3 mb-3">
            <div className={`p-2 rounded-lg ${color} group-hover:scale-110 transition-transform duration-300`}>
              {icon}
            </div>
            <h3 className="text-sm font-semibold text-slate-700 group-hover:text-slate-900 transition-colors">
              {title}
            </h3>
          </div>

          <div className="space-y-2">
            <div className="text-3xl font-bold text-slate-900">{value}</div>
            {description && (
              <p className="text-sm text-slate-500">{description}</p>
            )}
            {change && (
              <div className={`inline-flex items-center px-2 py-1 rounded-full text-xs font-medium ${changeColors[changeType]}`}>
                {changeType === "increase" && <ArrowUpIcon size="sm" className="mr-1" />}
                {changeType === "decrease" && <ArrowDownIcon size="sm" className="mr-1" />}
                {change}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

// Компонент прогрес-бару з покращеним дизайном
interface AdvancedProgressProps {
  label: string;
  value: number;
  max: number;
  color: string;
  showPercentage?: boolean;
  size?: "sm" | "md" | "lg";
}

const AdvancedProgress: React.FC<AdvancedProgressProps> = ({
  label,
  value,
  max,
  color,
  showPercentage = true,
  size = "md",
}) => {
  const percentage = Math.min((value / max) * 100, 100);

  const sizeClasses = {
    sm: "h-2",
    md: "h-3",
    lg: "h-4",
  };

  return (
    <div className="space-y-2">
      <div className="flex justify-between items-center">
        <span className="text-sm font-medium text-slate-700">{label}</span>
        <div className="flex items-center space-x-2">
          {showPercentage && (
            <span className="text-sm font-semibold text-slate-900">
              {percentage.toFixed(1)}%
            </span>
          )}
          <span className="text-xs text-slate-500">
            {value}/{max}
          </span>
        </div>
      </div>
      <div className="w-full bg-slate-200 rounded-full overflow-hidden">
        <div
          className={`${sizeClasses[size]} rounded-full transition-all duration-500 ease-out ${color}`}
          style={{ width: `${percentage}%` }}
        />
      </div>
    </div>
  );
};

// Компонент системного здоров'я
const SystemHealthWidget: React.FC = () => {
  const { t } = useI18n();
  const [metrics, setMetrics] = useState<SystemMetrics | null>(null);

  useEffect(() => {
    const fetchMetrics = async () => {
      try {
        const response = await fetch('/api/real-time-metrics');
        if (response.ok) {
          const data = await response.json();
          setMetrics(data.performance_data);
        }
      } catch (error) {
        console.error('Failed to fetch metrics:', error);
      }
    };

    fetchMetrics();
    const interval = setInterval(fetchMetrics, 5000);
    return () => clearInterval(interval);
  }, []);

  const getHealthStatus = (cpu: number, memory: number) => {
    if (cpu > 80 || memory > 85) return { status: 'critical', color: 'text-red-600', bg: 'bg-red-50' };
    if (cpu > 60 || memory > 70) return { status: 'warning', color: 'text-amber-600', bg: 'bg-amber-50' };
    return { status: 'healthy', color: 'text-emerald-600', bg: 'bg-emerald-50' };
  };

  if (!metrics) {
    return (
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
        <div className="animate-pulse space-y-4">
          <div className="h-4 bg-slate-200 rounded w-1/3"></div>
          <div className="space-y-2">
            <div className="h-3 bg-slate-200 rounded"></div>
            <div className="h-3 bg-slate-200 rounded w-2/3"></div>
          </div>
        </div>
      </div>
    );
  }

  const health = getHealthStatus(metrics.cpu_usage, metrics.memory_usage);

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
      <div className="flex items-center justify-between mb-6">
        <h3 className="text-lg font-semibold text-slate-900">Системне здоров'я</h3>
        <div className={`flex items-center space-x-2 px-3 py-1 rounded-full ${health.bg}`}>
          <div className={`w-2 h-2 rounded-full ${health.color.replace('text-', 'bg-')}`}></div>
          <span className={`text-sm font-medium ${health.color}`}>
            {health.status === 'healthy' ? 'Здорова' : health.status === 'warning' ? 'Попередження' : 'Критично'}
          </span>
        </div>
      </div>

      <div className="space-y-4">
        <AdvancedProgress
          label="Використання CPU"
          value={metrics.cpu_usage}
          max={100}
          color="bg-gradient-to-r from-blue-500 to-blue-600"
        />
        <AdvancedProgress
          label="Використання пам'яті"
          value={metrics.memory_usage}
          max={100}
          color="bg-gradient-to-r from-emerald-500 to-emerald-600"
        />
        <AdvancedProgress
          label="Мережевий трафік"
          value={metrics.network_in + metrics.network_out}
          max={1000}
          color="bg-gradient-to-r from-purple-500 to-purple-600"
        />
      </div>
    </div>
  );
};

// Компонент активності в реальному часі
const RealTimeActivity: React.FC = () => {
  const { t } = useI18n();
  const [activities, setActivities] = useState<any[]>([]);

  useEffect(() => {
    const generateActivity = () => {
      const types = ['client_connected', 'task_completed', 'error_occurred', 'system_update'];
      const newActivity = {
        id: Date.now(),
        type: types[Math.floor(Math.random() * types.length)],
        message: `Активність ${Date.now()}`,
        timestamp: new Date(),
        severity: Math.random() > 0.7 ? 'high' : Math.random() > 0.4 ? 'medium' : 'low'
      };

      setActivities(prev => [newActivity, ...prev.slice(0, 4)]);
    };

    const interval = setInterval(generateActivity, 3000);
    return () => clearInterval(interval);
  }, []);

  const getActivityIcon = (type: string) => {
    switch (type) {
      case 'client_connected': return <UsersIcon size="sm" className="text-emerald-600" />;
      case 'task_completed': return <CheckIcon size="sm" className="text-blue-600" />;
      case 'error_occurred': return <ErrorIcon size="sm" className="text-red-600" />;
      default: return <ProcessingIcon size="sm" className="text-slate-600" />;
    }
  };

  const getActivityColor = (severity: string) => {
    switch (severity) {
      case 'high': return 'border-l-red-500 bg-red-50';
      case 'medium': return 'border-l-amber-500 bg-amber-50';
      default: return 'border-l-emerald-500 bg-emerald-50';
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
      <div className="flex items-center justify-between mb-6">
        <h3 className="text-lg font-semibold text-slate-900">Активність в реальному часі</h3>
        <div className="flex items-center space-x-2">
          <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></div>
          <span className="text-sm text-slate-500">Live</span>
        </div>
      </div>

      <div className="space-y-3">
        {activities.length === 0 ? (
          <div className="text-center py-8">
            <div className="text-slate-400 mb-2">
              <ProcessingIcon size="lg" />
            </div>
            <p className="text-sm text-slate-500">Очікування активності...</p>
          </div>
        ) : (
          activities.map((activity, index) => (
            <div
              key={activity.id}
              className={`p-3 rounded-lg border-l-4 transition-all duration-300 ${getActivityColor(activity.severity)}`}
              style={{ animationDelay: `${index * 0.1}s` }}
            >
              <div className="flex items-center space-x-3">
                {getActivityIcon(activity.type)}
                <div className="flex-1">
                  <p className="text-sm font-medium text-slate-900">{activity.message}</p>
                  <p className="text-xs text-slate-500">
                    {activity.timestamp.toLocaleTimeString()}
                  </p>
                </div>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

// Компонент швидких дій
const QuickActions: React.FC = () => {
  const { t } = useI18n();

  const actions = [
    {
      title: 'Перезапустити систему',
      description: 'Безпечний перезапуск всіх сервісів',
      icon: <ProcessingIcon size="md" className="text-blue-600" />,
      color: 'bg-blue-50 hover:bg-blue-100',
      action: () => console.log('Restart system'),
    },
    {
      title: 'Очистити кеш',
      description: 'Видалити тимчасові файли',
      icon: <MemoryIcon size="md" className="text-emerald-600" />,
      color: 'bg-emerald-50 hover:bg-emerald-100',
      action: () => console.log('Clear cache'),
    },
    {
      title: 'Експорт логів',
      description: 'Завантажити системні логи',
      icon: <TasksIcon size="md" className="text-amber-600" />,
      color: 'bg-amber-50 hover:bg-amber-100',
      action: () => console.log('Export logs'),
    },
    {
      title: 'Налаштування',
      description: 'Конфігурація системи',
      icon: <CpuIcon size="md" className="text-purple-600" />,
      color: 'bg-purple-50 hover:bg-purple-100',
      action: () => console.log('Settings'),
    },
  ];

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
      <h3 className="text-lg font-semibold text-slate-900 mb-6">Швидкі дії</h3>

      <div className="grid grid-cols-2 gap-3">
        {actions.map((action, index) => (
          <button
            key={index}
            onClick={action.action}
            className={`p-4 rounded-lg text-left transition-all duration-300 transform hover:scale-105 ${action.color}`}
          >
            <div className="flex items-center space-x-3 mb-2">
              {action.icon}
              <h4 className="text-sm font-semibold text-slate-900">{action.title}</h4>
            </div>
            <p className="text-xs text-slate-600">{action.description}</p>
          </button>
        ))}
      </div>
    </div>
  );
};

// Головний компонент Dashboard
export const Dashboard: React.FC = () => {
  const { t } = useI18n();
  const { state } = useStatus();
  const [timeRange, setTimeRange] = useState<'1h' | '6h' | '24h' | '7d'>('24h');

  // Обчислення статистики клієнтів
  const clientStats: ClientStats = useMemo(() => {
    const clients = state.clients || [];
    const connected = clients.filter((c: any) => c.connection_status === 'connected');
    return {
      total: clients.length,
      connected: connected.length,
      workers: clients.filter((c: any) => c.client_type === 'worker').length,
      apiWorkers: clients.filter((c: any) => c.client_type === 'worker_api').length,
      bots: clients.filter((c: any) => c.client_type === 'bot').length,
      streamHubs: clients.filter((c: any) => c.client_type === 'stream_hub').length,
    };
  }, [state.clients]);

  // Фейкові дані для демонстрації
  const taskStats: TaskStats = {
    total: 1247,
    completed: 1156,
    failed: 23,
    pending: 45,
    processing: 23,
  };

  const handleTimeRangeChange = useCallback((range: '1h' | '6h' | '24h' | '7d') => {
    setTimeRange(range);
  }, []);

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-blue-50 to-indigo-50 p-6">
      <div className="max-w-7xl mx-auto space-y-8">
        {/* Заголовок */}
        <div className="text-center space-y-4">
          <h1 className="text-4xl font-bold bg-gradient-to-r from-blue-600 via-purple-600 to-indigo-600 bg-clip-text text-transparent">
            🏠 Панель керування TetraCore
          </h1>
          <p className="text-lg text-slate-600 max-w-2xl mx-auto">
            Моніторинг та управління системою в реальному часі
          </p>

          {/* Селектор часового діапазону */}
          <div className="flex justify-center">
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-1">
              {(['1h', '6h', '24h', '7d'] as const).map((range) => (
                <button
                  key={range}
                  onClick={() => handleTimeRangeChange(range)}
                  className={`px-4 py-2 rounded-lg text-sm font-medium transition-all duration-300 ${
                    timeRange === range
                      ? 'bg-blue-500 text-white shadow-lg'
                      : 'text-slate-600 hover:bg-slate-100'
                  }`}
                >
                  {range === '1h' ? 'Остання година' : 
                   range === '6h' ? 'Останні 6 годин' :
                   range === '24h' ? 'Останні 24 години' : 'Останній тиждень'}
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Героїчні метрики */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <HeroMetric
            title="Активні клієнти"
            value={clientStats.connected}
            subtitle={`з ${clientStats.total} всього клієнтів`}
            icon={<UsersIcon size="lg" />}
            gradient="bg-gradient-to-br from-blue-500 via-blue-600 to-blue-700"
            trend={{ value: "100% онлайн", isPositive: true }}
          />

          <HeroMetric
            title="Навантаження CPU"
            value="19%"
            subtitle="Середнє використання"
            icon={<CpuIcon size="lg" />}
            gradient="bg-gradient-to-br from-emerald-500 via-emerald-600 to-emerald-700"
            trend={{ value: "Нормальне", isPositive: true }}
          />

          <HeroMetric
            title="Використання пам'яті"
            value="71%"
            subtitle="Оперативна пам'ять"
            icon={<MemoryIcon size="lg" />}
            gradient="bg-gradient-to-br from-amber-500 via-amber-600 to-amber-700"
            trend={{ value: "Стабільно", isPositive: true }}
          />

          <HeroMetric
            title="Стан системи"
            value="Здорова"
            subtitle="Загальний статус"
            icon={<AnimatedHeartIcon size="lg" />}
            gradient="bg-gradient-to-br from-emerald-500 via-emerald-600 to-emerald-700"
          />
