            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
              <StatCard
                title="Всі воркери"
                value={clientStats.workers + clientStats.apiWorkers}
                icon={<CpuIcon size="md" />}
                color="bg-blue-100 text-blue-600"
                description="Загальна кількість"
                change="+2.5%"
                changeType="increase"
              />

              <StatCard
                title="Воркери"
                value={clientStats.workers}
                icon={<ProcessingIcon size="md" />}
                color="bg-emerald-100 text-emerald-600"
                description="Стандартні воркери"
              />

              <StatCard
                title="API-воркери"
                value={clientStats.apiWorkers}
                icon={<AlertIcon size="md" />}
                color="bg-amber-100 text-amber-600"
                description="API обробники"
              />

              <StatCard
                title="Активні сервери Бота"
                value={clientStats.bots}
                icon={<UsersIcon size="md" />}
                color="bg-purple-100 text-purple-600"
                description="Підключені боти"
              />
            </div>

            {/* Системне здоров'я */}
            <SystemHealthWidget />
          </div>

          {/* Права колонка - активність та дії */}
          <div className="space-y-6">
            <RealTimeActivity />
            <QuickActions />
          </div>
        </div>

        {/* Нижня секція - стан системи */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          {/* Стан системи */}
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
            <h3 className="text-lg font-semibold text-slate-900 mb-6 flex items-center">
              <span className="bg-gradient-to-r from-slate-600 to-slate-800 bg-clip-text text-transparent">
                💻 Стан системи
              </span>
            </h3>

            <div className="grid grid-cols-2 gap-4">
              <div className="flex items-center justify-between p-3 bg-emerald-50 rounded-lg">
                <div className="flex items-center space-x-2">
                  <div className="w-3 h-3 bg-emerald-500 rounded-full"></div>
                  <span className="text-sm font-medium text-slate-700">WebSocket Server</span>
                </div>
                <span className="text-xs text-emerald-600 font-semibold">Комунікація в реальному часі</span>
              </div>

              <div className="flex items-center justify-between p-3 bg-red-50 rounded-lg">
                <div className="flex items-center space-x-2">
                  <div className="w-3 h-3 bg-red-500 rounded-full"></div>
                  <span className="text-sm font-medium text-slate-700">Redis Cache</span>
                </div>
                <span className="text-xs text-red-600 font-semibold">Шар кешування даних</span>
              </div>

              <div className="flex items-center justify-between p-3 bg-emerald-50 rounded-lg">
                <div className="flex items-center space-x-2">
                  <div className="w-3 h-3 bg-emerald-500 rounded-full"></div>
                  <span className="text-sm font-medium text-slate-700">Client Manager</span>
                </div>
                <span className="text-xs text-emerald-600 font-semibold">Управління з'єднаннями</span>
              </div>

              <div className="flex items-center justify-between p-3 bg-emerald-50 rounded-lg">
                <div className="flex items-center space-x-2">
                  <div className="w-3 h-3 bg-emerald-500 rounded-full"></div>
                  <span className="text-sm font-medium text-slate-700">Task Router</span>
                </div>
                <span className="text-xs text-emerald-600 font-semibold">Розподіл завдань</span>
              </div>
            </div>

            <div className="mt-6 pt-4 border-t border-slate-200">
              <div className="flex items-center justify-between">
                <span className="text-sm text-slate-600">Версія системи: 1.0.0</span>
                <div className="flex items-center space-x-2">
                  <span className="text-sm text-slate-600">Статус з'єднання</span>
                  <div className="flex items-center space-x-1">
                    <div className="w-2 h-2 bg-emerald-500 rounded-full"></div>
                    <span className="text-sm font-medium text-emerald-600">Онлайн</span>
                    <span className="text-sm text-slate-500">2</span>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Метрики продуктивності */}
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
            <h3 className="text-lg font-semibold text-slate-900 mb-6 flex items-center">
              <span className="bg-gradient-to-r from-amber-600 to-amber-800 bg-clip-text text-transparent">
                ⚡ Метрики продуктивності
              </span>
            </h3>

            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <span className="text-sm font-medium text-slate-700">Час відповіді</span>
                <span className="text-2xl font-bold text-blue-600">0ms</span>
              </div>

              <div className="flex items-center justify-between">
                <span className="text-sm font-medium text-slate-700">Пропускна здатність</span>
                <span className="text-2xl font-bold text-emerald-600">0 req/s</span>
              </div>

              <div className="flex items-center justify-between">
                <span className="text-sm font-medium text-slate-700">Рівень помилок</span>
                <span className="text-2xl font-bold text-emerald-600">0.0%</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};
